private enum class RoleFilter{ALL,ADMIN,MANAGER,SALES};private enum class ActiveFilter{ALL,ACTIVE,INACTIVE}
@Composable fun EmployeesScreen(vm:EmployeesViewModel=viewModel()){
 val state=vm.state.collectAsStateWithLifecycle().value;val context=state.context;var search by remember{mutableStateOf("")};var role by remember{mutableStateOf(RoleFilter.ALL)};var active by remember{mutableStateOf(ActiveFilter.ALL)};var adding by remember{mutableStateOf(false)};var editing by remember{mutableStateOf<Employee?>(null)};var confirm by remember{mutableStateOf<Employee?>(null)};var profileSetup by remember{mutableStateOf(false)}
 if(context==null&&state.loading){LoadingScreen("Loading employees…");return};if(context==null){RetryScreen(state.error?:"Employees couldn't be loaded.",vm::refresh);return};if(profileSetup){CompanyProfileScreen(onComplete={profileSetup=false;vm.refresh()});return}
 val visible=context.employees.filter{it.name.contains(search,true)||it.email.contains(search,true)||it.phone?.contains(search,true)==true}.filter{role==RoleFilter.ALL||it.role.name==role.name}.filter{active==ActiveFilter.ALL||if(active==ActiveFilter.ACTIVE)isActiveEmployee(it) else !isActiveEmployee(it)}
 Box(Modifier.fillMaxSize()){
  LazyColumn(Modifier.fillMaxSize().padding(horizontal=14.dp),contentPadding=PaddingValues(bottom=88.dp),verticalArrangement=Arrangement.spacedBy(9.dp)){
   item{Spacer(Modifier.height(6.dp));SeatSummary(context);OutlinedTextField(search,{search=it},Modifier.fillMaxWidth(),singleLine=true,label={Text("Search employees")},leadingIcon={Icon(Icons.Default.Search,null)});FilterRow(role,{role=it},active,{active=it});if(state.emailVerified==false){ContentCard("Verify your email","Required before adding Managers or Sales employees."){Button(vm::resendVerification,enabled=!state.verificationSending){Text(if(state.verificationSending)"Sending…" else "Resend verification email")}}};if(state.companyProfileComplete==false){ContentCard("Complete company details","Required before adding Managers or Sales employees."){Button({profileSetup=true}){Text("Complete company details")}}};state.error?.let{MessageBanner(it,vm::dismiss)};state.notice?.let{Surface(Modifier.fillMaxWidth(),color=MaterialTheme.colorScheme.primaryContainer,shape=MaterialTheme.shapes.medium){Text(it,Modifier.padding(10.dp))}}}
   if(visible.isEmpty())item{ContentCard("No employees found",if(context.employees.isEmpty())"Add your first team member." else "Try changing the filters.")}
   items(visible,key={it.id}){employee->EmployeeCard(employee,context.teamStructure,state.mutating,{editing=employee},{confirm=employee})}
   if(state.loading)item{LinearProgressIndicator(Modifier.fillMaxWidth())}
  }
  if(context.canManage){ExtendedFloatingActionButton(text={Text("Add User")},icon={Icon(Icons.Default.PersonAdd,null)},onClick={adding=true},modifier=Modifier.align(androidx.compose.ui.Alignment.BottomEnd).padding(18.dp))}
 }
 if(adding)AddEmployeeDialog(context,state.mutating,{adding=false}){request->vm.create(request){adding=false}}
 editing?.let{employee->EditEmployeeDialog(employee,context,state.mutating,{editing=null},saveDetails={request->vm.edit(request){editing=null}},changeRole={request->vm.changeRole(request){editing=null}},resetDevice={vm.resetDevice(employee){editing=null}})}
 confirm?.let{employee->AlertDialog(onDismissRequest={confirm=null},title={Text("${employeeAction(employee)}?")},text={Text(employee.name)},confirmButton={Button({vm.setActive(employee,!isActiveEmployee(employee));confirm=null},enabled=!state.mutating){Text(employeeAction(employee))}},dismissButton={TextButton({confirm=null}){Text("Cancel")}})}
}

@Composable private fun SeatSummary(context:EmployeeContext){val e=context.entitlement;OutlinedCard(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text("Team seats",fontWeight=FontWeight.Bold);LazyRow(horizontalArrangement=Arrangement.spacedBy(6.dp)){item{StatusChip("Admin ${e.adminUsage} / ${limit(e.adminLimit)}")};if(context.teamStructure!=TeamStructure.SALES_ONLY)item{StatusChip("Manager ${e.managerUsage} / ${limit(e.managerLimit)}")};item{StatusChip("Sales ${e.salesUsage} / ${limit(e.salesLimit)}")};item{StatusChip("Inactive ${context.employees.count{!isActiveEmployee(it)}}")}}}}}
private fun limit(value:Int?)=value?.toString()?:"Unlimited"
@Composable private fun FilterRow(role:RoleFilter,onRole:(RoleFilter)->Unit,active:ActiveFilter,onActive:(ActiveFilter)->Unit){Column(verticalArrangement=Arrangement.spacedBy(4.dp)){LazyRow(horizontalArrangement=Arrangement.spacedBy(6.dp)){items(RoleFilter.entries){item->FilterChip(role==item,{onRole(item)},{Text(if(item==RoleFilter.ADMIN)"Administrators" else item.name.lowercase().replaceFirstChar{it.uppercase()})})}};Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){ActiveFilter.entries.forEach{item->FilterChip(active==item,{onActive(item)},{Text(item.name.lowercase().replaceFirstChar{it.uppercase()})})}}}}

@Composable private fun EmployeeCard(employee:Employee,structure:TeamStructure,busy:Boolean,onEdit:()->Unit,onActive:()->Unit){OutlinedCard(Modifier.fillMaxWidth()){Column(Modifier.padding(13.dp),verticalArrangement=Arrangement.spacedBy(4.dp)){Row{Column(Modifier.weight(1f)){Text(employee.name,style=MaterialTheme.typography.titleMedium,maxLines=1,overflow=TextOverflow.Ellipsis);Text(employee.email,maxLines=1,overflow=TextOverflow.Ellipsis,style=MaterialTheme.typography.bodySmall)};StatusChip(if(isActiveEmployee(employee))"Active" else "Inactive")};Text(roleLabel(employee),style=MaterialTheme.typography.labelMedium);employee.phone?.let{Text(it,style=MaterialTheme.typography.bodySmall)};if(structure!=TeamStructure.SALES_ONLY&&employee.role==MobileRole.SALES)Text("Manager: ${employee.manager?.name?:"Unassigned"}",style=MaterialTheme.typography.bodySmall,color=SalesMuted);Row(horizontalArrangement=Arrangement.spacedBy(8.dp)){OutlinedButton(onEdit,enabled=!busy,modifier=Modifier.weight(1f)){Text("Edit User")};TextButton(onActive,enabled=!busy,modifier=Modifier.weight(1f)){Text(if(isActiveEmployee(employee))"Deactivate" else "Reactivate")}}}}}
private fun roleLabel(e:Employee)=when(e.role){MobileRole.ADMIN->"Additional Admin";MobileRole.MANAGER->if(e.managerType==ManagerType.MANAGER_ONLY)"Office Manager" else "Sales Manager";MobileRole.SALES->"Sales Employee";MobileRole.PRIMARY_ADMIN->"Primary Admin"}
private fun hasSeat(usage:Int,limit:Int?)=limit==null||usage<limit

@Composable private fun AddEmployeeDialog(context:EmployeeContext,busy:Boolean,dismiss:()->Unit,submit:(CreateEmployeeRequest)->Unit){
 val managersEnabled=context.teamStructure==TeamStructure.MANAGERS_AND_SALES;var role by remember{mutableStateOf(MobileRole.SALES)};var managerType by remember{mutableStateOf(ManagerType.FIELD_MANAGER)};var name by remember{mutableStateOf("")};var email by remember{mutableStateOf("")};var phone by remember{mutableStateOf("")};var code by remember{mutableStateOf("")};var designation by remember{mutableStateOf("")};var joining by remember{mutableStateOf("")};var password by remember{mutableStateOf("")};var confirm by remember{mutableStateOf("")};var visible by remember{mutableStateOf(false)};var managerId by remember{mutableStateOf<String?>(null)};var branchScope by remember{mutableStateOf("ALL_BRANCHES")};val selectedBranches=remember{mutableStateListOf<String>()};val managers=selectableManagers(context.employees)
 val normalizedPhone=phone.replace(Regex("[\\s().-]"),"");val validPhone=phone.isBlank()||Regex("^\\+?[1-9]\\d{6,14}$").matches(normalizedPhone);val strong=password.length in 12..200&&password.any(Char::isLowerCase)&&password.any(Char::isUpperCase)&&password.any(Char::isDigit);val valid=name.trim().length>=2&&android.util.Patterns.EMAIL_ADDRESS.matcher(email.trim()).matches()&&validPhone&&strong&&password==confirm&&(branchScope=="ALL_BRANCHES"||role==MobileRole.ADMIN||selectedBranches.isNotEmpty())
 AlertDialog(onDismissRequest={if(!busy)dismiss()},title={Text("Add User")},text={Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(7.dp)){Text("Role",fontWeight=FontWeight.Bold);LazyRow(horizontalArrangement=Arrangement.spacedBy(5.dp)){items(listOf(MobileRole.ADMIN,MobileRole.MANAGER,MobileRole.SALES).filter{it!=MobileRole.MANAGER||managersEnabled}){item->FilterChip(role==item,{role=item;managerId=null},{Text(if(item==MobileRole.ADMIN)"Admin" else item.name.lowercase().replaceFirstChar{it.uppercase()})})}};if(role==MobileRole.MANAGER)ManagerTypePicker(managerType){managerType=it};OutlinedTextField(name,{name=it},label={Text("Full name")});OutlinedTextField(email,{email=it},label={Text("Email")},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Email));OutlinedTextField(phone,{phone=it},label={Text("Phone (optional)")},keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Phone));if(role!=MobileRole.ADMIN){OutlinedTextField(code,{code=it},label={Text("Employee code (optional)")});OutlinedTextField(designation,{designation=it},label={Text("Designation (optional)")});OutlinedTextField(joining,{joining=it},label={Text("Date of joining · YYYY-MM-DD")});if(role==MobileRole.SALES&&managersEnabled)ManagerPicker(managers,managerId){managerId=it};BranchAccessEditor(context.branches,branchScope,{branchScope=it},selectedBranches)};OutlinedTextField(password,{password=it},label={Text("Password")},visualTransformation=if(visible)VisualTransformation.None else PasswordVisualTransformation(),trailingIcon={IconButton({visible=!visible}){Icon(if(visible)Icons.Default.VisibilityOff else Icons.Default.Visibility,null)}});OutlinedTextField(confirm,{confirm=it},label={Text("Confirm password")},visualTransformation=PasswordVisualTransformation())}},confirmButton={Button({submit(CreateEmployeeRequest(role,name.trim(),email.trim(),phone.ifBlank{null},code.ifBlank{null},designation.ifBlank{null},joining.ifBlank{null},password,confirm,managerId,if(role==MobileRole.MANAGER)managerType else null,if(role==MobileRole.ADMIN)"ALL_BRANCHES" else branchScope,if(role==MobileRole.ADMIN||branchScope=="ALL_BRANCHES")emptyList() else selectedBranches.toList()))},enabled=valid&&!busy&&roleSeatAvailable(context,role)){Text(if(busy)"Saving…" else "Create")}},dismissButton={TextButton(dismiss){Text("Cancel")}})
}
private fun roleSeatAvailable(c:EmployeeContext,role:MobileRole)=when(role){MobileRole.ADMIN->hasSeat(c.entitlement.adminUsage,c.entitlement.adminLimit);MobileRole.MANAGER->hasSeat(c.entitlement.managerUsage,c.entitlement.managerLimit);MobileRole.SALES->hasSeat(c.entitlement.salesUsage,c.entitlement.salesLimit);else->false}

@Composable private fun EditEmployeeDialog(employee:Employee,context:EmployeeContext,busy:Boolean,dismiss:()->Unit,saveDetails:(EditEmployeeRequest)->Unit,changeRole:(ChangeEmployeeRoleRequest)->Unit,resetDevice:()->Unit){
 var name by remember(employee.id){mutableStateOf(employee.name)};var email by remember(employee.id){mutableStateOf(employee.email)};var phone by remember(employee.id){mutableStateOf(employee.phone?:"")};var code by remember(employee.id){mutableStateOf(employee.employeeCode?:"")};var designation by remember(employee.id){mutableStateOf(employee.designation?:"")};var joining by remember(employee.id){mutableStateOf(employee.dateOfJoining?.take(10)?:"")};var managerId by remember(employee.id){mutableStateOf(employee.managerId)};var managerType by remember(employee.id){mutableStateOf(employee.managerType?:ManagerType.FIELD_MANAGER)};var branchScope by remember(employee.id){mutableStateOf(employee.branchAccessScope)};val branchIds=remember(employee.id){mutableStateListOf<String>().apply{addAll(employee.branchIds)}};var travelEnabled by remember(employee.id){mutableStateOf(employee.travelAllowanceEnabled)};var travelRate by remember(employee.id){mutableStateOf(employee.travelRatePerKm?:"")};var roleChoice by remember(employee.id){mutableStateOf(when(employee.role){MobileRole.ADMIN->"ADDITIONAL_ADMIN";MobileRole.MANAGER->if(employee.managerType==ManagerType.MANAGER_ONLY)"OFFICE_MANAGER" else "SALES_MANAGER";else->"SALES_EMPLOYEE"})};var confirmReset by remember(employee.id){mutableStateOf(false)};val managers=selectableManagers(context.employees).filter{it.id!=employee.id}
 AlertDialog(onDismissRequest={if(!busy)dismiss()},title={Text("Edit User")},text={Column(Modifier.verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("Role & Assignment",fontWeight=FontWeight.Bold);listOf("ADDITIONAL_ADMIN" to "Additional Admin","SALES_MANAGER" to "Sales Manager","OFFICE_MANAGER" to "Office Manager","SALES_EMPLOYEE" to "Sales Employee").filter{context.teamStructure!=TeamStructure.SALES_ONLY||!it.first.contains("MANAGER")}.forEach{(value,label)->FilterChip(roleChoice==value,{roleChoice=value},{Text(label)})};if(roleChoice=="SALES_EMPLOYEE"&&context.teamStructure!=TeamStructure.SALES_ONLY)ManagerPicker(managers,managerId){managerId=it};Button({changeRole(ChangeEmployeeRoleRequest(employeeId=employee.id,role=roleChoice,managerId=if(roleChoice=="SALES_EMPLOYEE")managerId else null))},enabled=!busy,modifier=Modifier.fillMaxWidth()){Text("Save Role / Assignment")};HorizontalDivider();Text("User Details",fontWeight=FontWeight.Bold);OutlinedTextField(name,{name=it},label={Text("Name")});OutlinedTextField(email,{email=it},label={Text("Email")});OutlinedTextField(phone,{phone=it},label={Text("Phone")});if(employee.role!=MobileRole.ADMIN){OutlinedTextField(code,{code=it},label={Text("Employee code")});OutlinedTextField(designation,{designation=it},label={Text("Designation")});OutlinedTextField(joining,{joining=it},label={Text("Date of joining · YYYY-MM-DD")});if(employee.role==MobileRole.MANAGER)ManagerTypePicker(managerType){managerType=it};if(employee.role==MobileRole.SALES&&context.teamStructure!=TeamStructure.SALES_ONLY)ManagerPicker(managers,managerId){managerId=it};BranchAccessEditor(context.branches,branchScope,{branchScope=it},branchIds);Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Travel allowance");Switch(travelEnabled,{travelEnabled=it})};OutlinedTextField(travelRate,{travelRate=it.filter{ch->ch.isDigit()||ch=='.'}},label={Text("Custom ₹ / km (optional)")})};Button({saveDetails(EditEmployeeRequest(employeeId=employee.id,name=name.trim(),email=email.trim(),phone=phone.ifBlank{null},employeeCode=code.ifBlank{null},designation=designation.ifBlank{null},dateOfJoining=joining.ifBlank{null},managerId=managerId,managerType=if(employee.role==MobileRole.MANAGER)managerType else null,branchAccessScope=branchScope,branchIds=if(branchScope=="SELECTED_BRANCHES")branchIds.toList() else emptyList(),travelAllowanceEnabled=travelEnabled,travelRatePerKm=travelRate.ifBlank{null}))},enabled=!busy&&name.isNotBlank()&&email.isNotBlank(),modifier=Modifier.fillMaxWidth()){Text("Save Details")};if(context.canManage){HorizontalDivider();Text("Mobile Device",fontWeight=FontWeight.Bold);Text("Reset this when the employee changes phones. The current phone will be signed out and the next phone can register at sign-in.",style=MaterialTheme.typography.bodySmall,color=SalesMuted);OutlinedButton({confirmReset=true},enabled=!busy,modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.PhoneAndroid,null);Spacer(Modifier.width(6.dp));Text("Reset Registered Device")}}}},confirmButton={},dismissButton={TextButton(dismiss){Text("Close")}})
 if(confirmReset)AlertDialog(onDismissRequest={if(!busy)confirmReset=false},title={Text("Reset registered device?")},text={Text("${employee.name}'s current mobile session will be revoked. Their next phone will become the registered device after a successful sign-in.")},confirmButton={Button({confirmReset=false;resetDevice()},enabled=!busy){Text("Reset Device")}},dismissButton={TextButton({confirmReset=false}){Text("Cancel")}})
}

@Composable private fun ManagerTypePicker(value:ManagerType,change:(ManagerType)->Unit){Text("Manager Type",fontWeight=FontWeight.Bold);Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){FilterChip(value==ManagerType.FIELD_MANAGER,{change(ManagerType.FIELD_MANAGER)},{Text("Sales Manager")});FilterChip(value==ManagerType.MANAGER_ONLY,{change(ManagerType.MANAGER_ONLY)},{Text("Office Manager")})}}
@Composable private fun ManagerPicker(managers:List<Employee>,selected:String?,choose:(String?)->Unit){var expanded by remember{mutableStateOf(false)};Box{OutlinedButton({expanded=true},Modifier.fillMaxWidth()){Text(managers.firstOrNull{it.id==selected}?.name?:"No Manager assigned")};DropdownMenu(expanded,{expanded=false}){DropdownMenuItem({Text("No Manager assigned")},{choose(null);expanded=false});managers.forEach{manager->DropdownMenuItem({Text(manager.name)},{choose(manager.id);expanded=false})}}}}
@Composable private fun BranchAccessEditor(branches:List<BranchSummary>,scope:String,changeScope:(String)->Unit,selected:MutableList<String>){Text("Branch Access",fontWeight=FontWeight.Bold);Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){FilterChip(scope=="ALL_BRANCHES",{changeScope("ALL_BRANCHES")},{Text("All Branches")});FilterChip(scope=="SELECTED_BRANCHES",{changeScope("SELECTED_BRANCHES")},{Text("Selected")})};if(scope=="SELECTED_BRANCHES")branches.forEach{branch->Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("${branch.name} (${branch.code})",Modifier.weight(1f));Checkbox(branch.id in selected,{checked->if(checked&&branch.id !in selected)selected.add(branch.id) else if(!checked)selected.remove(branch.id)})}}}
